/* =============================================================================
   patch-notes.js — LOOTFLEET · "WHAT'S NEW" ON FIRST LOGIN TO A NEW BUILD
   -----------------------------------------------------------------------------
   Shows one card, once, the first time a player logs in after a build ships.

   WHAT GOES ON THIS CARD — the editorial rule, because it is the whole job:
   ONLY things a PLAYER can see, feel, or must act on. Not everything that
   changed in a build is player information. A migration, a refactor, a renamed
   function, a cache header — those are operator facts, and putting them here
   trains people to close the card without reading it, which costs us the one
   time it really matters.

   The test for each line: **would a player notice if we never told them?**
     · Their 5× speed pill is gone            → YES. Must be here.
     · Cargo runs stopped dropping fittings   → YES. A nerf. Must be here.
     · Their leaderboard row was frozen       → YES. They saw it and complained.
     · lb_upsert dropped an overload          → NO. That is a deploy note.
     · Loot blocking became one predicate     → NO. Same behaviour, better code.
     · A reserved rarity tier exists          → NO. It is not live. Saying so
                                                 just promises something absent.

   TONE: short, punchy, one line each. A player reads this in fifteen seconds
   standing in a queue. Anything longer is a changelog, and the changelog lives
   on the site.

   WHAT A NERF OWES THE PLAYER: it gets said out loud, in plain words, with what
   they keep. Silent removal of something a player is holding reads exactly like
   a bug — see CLAUDE.md. That is why the speed tiers and the cargo loot change
   lead the CHANGED block rather than hiding at the bottom of it.
   ========================================================================== */
(function () {
  'use strict';

  const BUILD = 739;
  // 736 CARRIES 730–735'S ROWS TOO. 729 is still what the population is running:
  // every build from 730 up was cut and verified without being pushed, and the card
  // is keyed on LF_BUILD in localStorage, so a 736-only card would mean nobody who
  // skipped those logins ever sees the Home Citadel changes, the Dread Core
  // scarcity pass, the contiguity bonus or the siege shield. Drop the older rows
  // once 736 has been live long enough for the population to turn over.
  // 730 CARRIES 729'S ROWS, AND THAT IS DELIBERATE. 729 shipped only hours before
  // 730 was cut, so most accounts had not logged into it yet. The card is keyed on
  // LF_BUILD in localStorage: replacing 729's card with a 730-only card would mean
  // anyone who missed the 729 login never sees any of those 24 rows. Same rule as
  // the 727/728 merge, one build later. When 730 has been live long enough that
  // the population has turned over, the next card may drop these rows.
  // (Historic note on the merge below.) 728 was cut but never pushed, so the live
  // build was 726 and a player jumping 726 to 729 would never have seen 728's card.
  // Same rule as the 727/728 merge: a skipped build owes its rows to the next
  // card. 729's own items are folded into the rows they belong to rather than
  // repeated at the bottom — the Eternum row states both halves of that licence
  // change, and the chat row states the launch gate it actually ships on.
  const NOTES = {
    build: 739,
    title: 'BUILD 739',
    sub: 'THE MOTHERSHIP has arrived — plus everything from 730 to 739.',
    groups: [
      { k: 'THE BIG TEN', c: '#ffd24d', rows: [
        ['☄', 'A mothership arrived — and 1,000 parts unlocks it', 'The Voidmaw was never alone. Its <b>mothership</b> has come to recover it — harvester drones, rocket volleys and collapse zones. Collect <b>1,000 Progenitor Parts</b> and the hull is yours to fly. No deadline: the event is permanent now, and every part you have ever banked carries over.'],
        ['✦', 'Its harvesters hunt you for the whole run', 'Two <b>harvester drones</b> launch at the start and never stop. They are slow, they <b>cannot be killed</b>, and they drag a burning wake you have to read the floor to avoid.'],
        ['⚔', 'Getting stronger finally helps in Home Citadel', 'Raider health used to be worked out from <b>your own damage</b>, so upgrading did nothing. Waves are now built for the wave — get ahead of it and they die faster. <b>No wave got harder.</b>'],
        ['⬢', 'The Aeternum’s death beams were doing far too much', 'Five beams were adding nearly <b>seven times your whole fleet’s damage</b>. Now they add one and a half between them. Still the strongest clear in the game — no longer an off switch.'],
        ['◈', 'Old retired fortresses pay like normal systems now', 'A few systems were quietly paying a <b>fortress bonus and a citadel bonus at once</b>, worth hundreds of times a fair rate. Fixed. <b>Nothing was taken from anyone</b> — you keep every citadel and everything you banked.'],
        ['⬡', 'A solid block of space is worth more than a sprawl', '<b>CONTIGUITY BONUS:</b> systems that touch each other pay more than the same number scattered across the map. Hold ground together.'],
        ['☁', 'Your progress survives playing on two devices', 'Several things could vanish when a save came in from another phone — <b>Prism Auras, forged Cores, your Cargo record, your mission boards</b>. They are all protected now.'],
        ['⚑', 'Your flagship stops switching itself', 'If you had the game open in two places, it could quietly put you back in your old hull mid-fight. The ship you are flying now always wins.'],
        ['⬢', 'THE BRIDGE — your hull, wing and formation on one screen', 'Everything about your fleet in one place, straight from the hangar. Global chat is open from any screen too.'],
        ['⚡', 'Two things cost more, on purpose', '<b>Nanocore Crates cost double</b> and <b>◇ Dread Cores are rarer</b> everywhere they drop. Both were far too cheap for what they buy. Nothing you already own is affected.'],
      ] },
      { k: 'NEW', c: '#7ce0a0', rows: [
        ['☄', 'THE MOTHERSHIP — a new Voidmaw season', 'The Voidmaw was never alone. Its <b>mothership</b> has come to recover it, and it fights nothing like the old boss. Same event, same two runs a day, same instant stage loot — <b>a brand new season board, starting at zero for everyone</b>, and no end date. Your <b>previous season prize is waiting to be collected</b> in the event and in your mail; coins, parts and the Voidmaw hull you were building all carry across untouched.<br><br>It brings three new weapons. <b>Two harvester drones</b> launch at the start and hunt you for the entire run — slow, relentless, and <b>they cannot be killed</b>. Let one touch you and it latches on: engines to 45% and <b>40% of your hull every second</b>, which is about two and a half seconds from full no matter what you fly. They also leave a <b>burning wake</b> behind them that lingers for a few seconds — crossing one costs hull and <b>slows you down</b>, so it costs more than it looks, and over a long run the wakes turn the arena into a maze. And the mothership fires <b>rocket volleys</b> from long range: each one takes <b>a fifth of your maximum hull</b>, but they fly to where you <i>were</i>, so keep moving and they miss. The collapsing red zones are still here but come <b>noticeably less often</b> — the harvesters are the pressure now.<br><br><b>A new grand prize: THE PROGENITOR.</b> Collect <b>1,000 parts</b> and you fly the mothership yourself — five cannon hardpoints, six fighter bays, and its own harvester drones that latch onto your enemies instead of you. <b>The Voidmaw is retired as a prize</b> — it belonged to the season that just closed. <b>Nothing has been taken:</b> every part you have banked is kept and now counts toward the Progenitor instead, so if you were close to the old 150 you are already a long way into the new one. Anyone who assembled a Voidmaw keeps it in their Hangar.'],
        ['〜', 'Harvesters — two drones that never stop', 'The mothership launches <b>two harvester drones</b>. They are <b>slow</b>, they hunt you for the entire run, and they <b>cannot be killed</b> — you can only outrun them. Let one touch you and it <b>latches</b>: your engines drop to <b>45%</b> and it strips <b>40% of your hull every second</b>. That is roughly <b>two and a half seconds from full</b>, whatever you fly — no hull survives a harvester. Break away the instant it grabs you.<br><br>They also leave a <b>burning wake</b> behind them that lingers for a few seconds. Crossing one costs <b>15% of your hull per second</b> and <b>slows you</b> — which keeps you in it longer than you meant to be. Over a long run the wakes turn the arena into a maze, and finding the clean line through it is the fight.'],
        ['🚀', 'Rocket volleys', 'Fired from long range, slow enough to read, and each one takes a flat <b>20% of your maximum hull</b> — five will kill anyone. They fly to where you <b>were</b>, so they always miss a moving pilot, and they exist to punish standing still while you deal with a harvester.'],
        ['🔴', 'Void collapse zones are rarer now', 'They still open and they still hit for 75% of your hull per second, but they arrive <b>much less often</b>. The harvesters and their wakes are the constant pressure in this season; stacking the old zone cadence on top left nowhere to stand.'],
      ] },
      { k: 'CHANGED', c: '#ffcf4d', rows: [
        ['✦', 'The Aeternum’s death beams are a weapon again, not an off switch', 'Each of the five beams was doing <b>135% of your whole fleet’s damage</b>, on its own, every second — so the array alone was <b>6.75× your entire build</b>, poured into five targets at once while your normal weapons were still firing. Anything it touched simply vanished, and nothing you flew into mattered. The array now has a <b>shared budget</b>: all five beams together add up to <b>1.5× your fleet damage</b>, split between them, so the Aeternum is still far and away the strongest clear in the game without deleting the fight. A beam also can no longer strip more than <b>half a target’s health per second</b>, so nothing dies to it instantly no matter how far your damage has scaled. Your hull, your hardpoints and your fleet score are untouched — only the beam’s share changes.'],
        ['⛰', 'Retired natural citadels are ordinary systems now — and no system stacks both bonuses', 'When the galaxy’s natural citadels were cut to a fixed <b>25</b>, the ones that lost the status were kept alive for any pilot already holding them. That was meant as protection and it created something the game cannot otherwise make. A retired fortress became an ordinary system, so a citadel could legally be <b>built</b> on it — and then it was handed its fortress status back <b>underneath</b> the citadel. The system then paid the <b>×1000</b> for being a natural fortress <i>and</i> the <b>×10 per rank</b> for the citadel on top, which is far beyond what either is worth and was never how it was meant to work. The same collision could happen in reverse for the current 25.<br><br>Two things change. The <b>48 retired fortresses are ordinary systems</b>, as the scarcity pass intended — the 25 real ones are unaffected. And where a citadel is standing on a natural fortress, <b>the citadel is what pays</b>: a normal system plus your citadel bonus, never both bonuses at once. <b>You keep the citadel you paid for and every resource it has already produced</b> — nothing is taken back, and your systems, ranks and defences are untouched. Hourly production on those specific systems drops, in some cases a great deal, and we would rather say that plainly than let you find it on your own.'],
        ['⚑', 'The Territory board is now called MY GALAXY', 'It only ever ranked the galaxy ground you hold — Void spires and House Citadels are income, but they have never counted toward it, and “territory” promised something wider than what the board measures. Its subtitle also read “Galaxy Tiles” while it has always ranked on <b>hourly revenue</b> rather than tile count; that now says so too. <b>Nothing about how you are ranked has changed</b> — same systems, same figure, same position.'],
        ['⌘', 'The Veridian now says what it actually counts', 'The mission-reward hull asked for “1,000 lifetime missions (any board)”, and that was never a count of missions: a daily order is worth <b>1</b>, a weekly <b>3</b> and a monthly <b>5</b>. So a pilot adding up their own completed orders could not reconcile their total with the bar, and the words “any board” actively suggested the boards were interchangeable at exactly the point where they are not. The requirement now reads <b>mission credit</b> and states what each board pays. <b>Nothing changed about the hull, the target or your progress</b> — your credit is exactly what it was, the bar is in the same place, and the figures are now read from the boards themselves so they cannot drift apart again.'],
        ['⚙', 'Home Citadel raiders stop scaling with your fleet', 'Raider health was worked out from <b>your own damage</b>, so every upgrade you bought was handed straight to the enemy and a wave cost the same amount of shooting whether you flew a starter hull or your best fleet. Getting stronger bought you nothing in this mode, which is exactly backwards for a base you are supposed to grow into. A wave is now built for <b>the fleet that wave expects</b> — once yours is past it, the raiders stop keeping up and start dying faster, and pushing deeper is something your fleet does rather than something only the clock does. <b>No wave can get harder than it is today.</b> If your fleet is at or under what the wave expects, the fight is unchanged down to the last shot; the change only ever cuts a wave down, never builds it up. Your wave number, towers, structures, production and pay are all untouched.'],
        ['⛴', 'Natural citadels are scarce on purpose — five per 100 levels', 'A natural citadel pays a thousand times what a resource field of its depth pays, which makes it the richest thing on the map — and how many existed was pure luck of the map seed. There were <b>73</b>, spread wildly: two in the shallowest level band and thirty in one of the deep ones. Now every 100 levels of the galaxy holds <b>exactly five</b>, so a fortress is worth hunting for at any depth and the shallow rings actually gained some. <b>A citadel you already hold stays yours and keeps paying exactly what it paid.</b> Nothing has been taken off your account: no income lost, no siege refunded, no fortress demoted under you. Retired locations become <b>boss systems</b> — same name, same resource, same rarity, and still well worth taking. Citadels you BUILT yourself are a different thing entirely and are completely untouched, wherever they stand.'],
        ['✦', 'The Eternum licence is actually reachable: ★30 and 300 cargo runs', 'It asked for <b>★100</b> and <b>1,000 secured cargo runs</b> — the better part of two years on either line, so the Celestial Class read as decoration rather than something to aim at. It now asks <b>★30</b> and <b>300 runs</b>, which finish in roughly the same season as each other instead of one hiding behind the other. Nothing else moved: still a Titan Sina in the hangar, still commissioned with a core that only the deepest Omega Cargo V manifest gives up, still the same yard bill. If you are already past either number, that line is simply done. And the hangar tile was printing <b>★50</b> while the licence actually wanted ★100 — so if you hit the number you were shown and were still refused, that was our bug, not your progress. Every figure on that card now comes off the licence itself.'],
        ['\u2699', 'Home Citadel wave pay is capped by the clock, not by waves', 'Every wave you clear still pays 2.2 hours of your base\u2019s production, and clearing waves still raises that production permanently. Your wave, your towers, your structures and every balance are untouched. What is new is a bank: it refills at 8 hours of pay per real hour and holds 24. Arrive after a break and the first dozen waves pay in full, exactly as before \u2014 chain waves for an hour and your works settle to 8\u00d7 what your base mines. Part crates and their cores are never lost; they queue and land as the bank refills. A wave\u2019s bonus is also now priced at the production rate you fought it at, rather than the rate it unlocks.'],
        ['◇', '◇ Dread Cores are rarer everywhere they drop', 'Cores buy Pilot Tree nodes — the only upgrade in the game that improves every ship you will ever fly — and they were arriving from six separate systems that had each been tuned on their own. Added up, the tree was filling faster than it was ever meant to. <b>Every core faucet now pays 30% of what it used to — that is a cut of 70%, not a cut of 30%</b>, and we said it badly the first time. In plain numbers: a Dreadnaught tier that read <b>95%</b> now reads <b>28.5%</b>, and a 5★ expedition that came home with 9–12 cores comes home with 2–4. Those are the intended figures, not a second bug on top of the change: the percentage printed on each hunt card is the real number and it came down with everything else, so what you are shown is still what you are rolling. It applies to the Dreadnaught Hunt’s tier odds, Home Citadel wave crates past Wave 50, Cargo Defense manifests, Fleet Exploration payouts and the Voidmaw stage drops. <b>Every core you already hold is yours, and every node you have unlocked stays unlocked</b> — nothing has been taken off your account and no node got more expensive. What changes is that rewards which used to guarantee a core are now a chance at one: a hunt or a 3★ expedition can come home empty. Where a Voidmaw stage would have paid a core and does not, it pays bonus gold instead, so no stage pays nothing. Cores from the Social and Alliance stores are unchanged.'],
        ['⬡', 'Command is sorted into six groups you can fold away', 'Twenty-five systems in one flat grid meant roughly two and a half screens of scrolling, with a live event and a finished season track weighing exactly the same as a screen you last opened in March. Command now sorts itself into <b>Live &amp; Events</b>, <b>Empire</b>, <b>Power</b>, <b>Workshop</b> and <b>More</b>, each under a heading that stays pinned as you scroll past it and <b>carries the count of everything waiting inside it</b> — so a group you have folded still tells you it wants you. Tap a heading to fold or unfold it, and the game remembers per device. <b>Nothing was removed, hidden or moved behind an extra tap</b>: all twenty-five are still one tap away, every lock reads exactly as it did, and every badge is the same number on the same card. The only thing that changed is the order — Voidmaw and My Galaxy now sit with the rest of their group rather than pinned to the top row.'],
        ['◈', 'Nanocore Crates cost twice what they did', 'A crate is <b>◈ 60,000</b> Prism Ingots and ten are <b>◈ 540,000</b> — double the old prices, with the same discount for buying ten. Nothing else about the crate moved: the same drop odds, the same cores, and duplicates still trade up at the same rates. <b>Every core and every ingot you already hold is untouched</b>, and nothing you have opened is affected.'],
      ] },
      { k: 'NEW', c: '#7fd1ff', rows: [
        ['⇄', 'Legendary nanocore duplicates finally buy something', 'Duplicates of every other rarity traded up. Legendary ones — the hardest thing in the crate table to see twice — had nowhere to go and no row on the screen to say so. <b>Five Legendary duplicates now buy a Legendary core for a hull you have not recovered one for yet.</b> It is a sidegrade rather than a tier jump, which is why it costs five and not ten, and it only ever hands over a core you are missing: once every hull has its Legendary the row says so instead of taking your dupes for another duplicate. Nothing about the 10 : 1 trades below it changed.'],
        ['⚔', 'Rival empires hold TERRITORY now, not scattered tiles', 'The rival layer decided every system on its own, so a rival’s holdings were confetti — two systems side by side almost always belonged to two different pilots, and no rival ever held a block of anything. The galaxy is cut into <b>spheres of influence</b> now: a neighbourhood belongs to one empire, and deeper in there are <b>strongholds</b> — solid blocs of one empire’s space, with sealed cores of their own that you have to break a border system to reach. <b>The same number of systems are rival-held as before, ring for ring</b> — you have exactly as much open ground to claim; it is the shape that changed. The shallow rings stay open frontier: strongholds only appear from <b>ring 6</b> outward, and the deepest space is where the real empires sit. Every empire is drawn in <b>its own colour</b> with a hard border around its territory, so two of them side by side no longer read as one — and a single stray claim stays plain red, because 1,065 of the claims on the map are lone systems and colouring every one of those would be the confetti again.'],
        ['🛡', 'TERRITORY DEFENDS ITSELF — no exposed border, no siege', 'A system whose <b>every border faces its own owner’s space</b> can no longer be attacked at all. Ring a system with six of your own and its core is sealed: an enemy has to take one of the border systems around it first, and only then does the way in open. It works for everyone, so a rival’s inner systems are shut to you the same way — and <b>allied space counts as one bloc</b>, so an ally’s tile shields yours exactly as your own does. The map shows it: a sealed system breathes inside its hex, and the ring of systems holding it — the shell you would have to break — lights its outer edge. Open any system for the reason in plain words, and on a sealed enemy core the sheet <b>names the border systems to hit</b> and flies you to one. Two things stay open on purpose: the galaxy’s <b>outer rim</b>, where borders face off the map, and your <b>home citadel</b>, which belongs to no one. Your systems list marks which of your holds are <b>⛨ SEALED</b> and which are the wall holding them, the galaxy list says <b>🛡 SEALED</b> instead of offering a target that would refuse, and every empire’s wall is drawn in its own colour — yours always the same ice white — so two rivals side by side never read as one territory. Nothing was taken away — no system changed hands, no shield expired, and a scattered empire plays exactly as it did.'],
        ['⬡', 'CONTIGUITY BONUS — a solid block of space is worth more than a sprawl', 'Systems you hold that <b>touch each other</b> now pay a bonus, on <b>every tile in the block</b>: <b>4 touching pays +100%</b> an hour, <b>10 pays +120%</b>, <b>30 pays +150%</b>, <b>50 pays +200%</b>. A qualifying block is outlined on the galaxy map as one territory with a hard border in its tier’s colour, so you can see the shape you are building. Each block is scored on its own size and you can hold as many as you like. Nothing was taken away to pay for this — every system you already hold earns at least what it earned before, and a scattered empire is untouched. The new pill under <b>◈ Systems</b> in My Galaxy shows your largest block, what it is paying and how many more tiles reach the next rung. Your home citadel is neutral ground and does not join a block.'],
        ['▣', 'THE BRIDGE — your hull, your wing and your formation on one sheet', 'A fifth button on the hangar dock opens the Bridge: the hull you are flying with every hardpoint it has mounted, your formation slots, and every other hull you own as a card you can compare and fly with one tap. The dock itself is unchanged and nothing new sits over the arena.'],
        ['➤', 'FIGHTER ASCENSION — four wing doctrines, at ★10', 'A new Command screen for pilots at <b>Pilot Ascension ★10</b>. Four permanent doctrines, bought a rank at a time, flown by <b>every fighter you launch</b> — out of your flagship’s bays and out of every carrier in your wing, on any hull, forever. <b>Corona Mantle</b> wraps each craft in a burning halo that eats whatever it flies through. <b>Phantom Lattice</b> gives each craft a spectral double that mirrors its strikes. <b>Nova Reclamation</b> turns every kill into a shockwave, and deep enough in, the wreck cooks off twice. <b>Apex Sortie</b> sends the whole wing to afterburner on a clock. Each rank costs gold, one Galaxy Resource and ◈ Prism Ingots — the first rank is affordable the day the gate opens, and rank 10 is a very long haul. Doctrines ride through every future ascension, and nothing is ever taken back. <b>Your wing trains to one doctrine at a time</b> — every rank you buy is kept forever, and switching between the ones you own is free and instant, so the cost of this system is the ranks and never the choice.'],
        ['◉', 'AUTO BEACON — 25,000 LootCoins, once', 'A permanent unlock in <b>Hangar ▸ Market ▸ Operations</b>: your distress beacon fires itself the moment it recharges, in every zone grind, whether you are watching or not. Nothing else changes — same recharge, same swarm, same kill value, and it still never fires during a boss. You can arm and disarm it whenever you like, and it survives ascension.'],
        ['◈', 'Run your empire from My Systems', 'Every hold in the list has its own controls now. Rank up a citadel — or raise one where there is none — at the price printed on the button, jump the galaxy map straight to that hex, or deploy there, all without closing the sheet and hunting for the tile. Sort by revenue, ring, citadel rank or name, and filter down to just your citadels. Your place in the list is kept when you buy, so working down a long empire is one pass.'],
        ['◈', 'Global chat, open from any screen', 'There is a CHAT chip in your top bar now. It opens a panel over whatever you are doing rather than a screen you have to leave the fight for — on a phone it sits above your controls, on a desktop it docks to the right, and the battle keeps running behind it either way. Tap any pilot’s name for their level, zone, power and fleet, and add them as a friend from there. Mute anyone you would rather not read and it follows your account onto every device; the ⚑ on a message reports it to us with the message attached. Two house rules worth knowing before you type: <b>posting unlocks at Level 10</b> (reading is open the moment you have an account), and <b>links are stripped</b> — nobody in this room can send you anywhere, which is the entire point. The room opens on the strict settings while it finds its feet, so there is a short wait between your own messages; we will loosen it once it has settled.'],
        ['▲', 'Every fighter marque flies its own airframe', 'A wing of Mauls and a wing of Talons used to be the same silhouette. Each marque has its own craft now — ten airframes in all, most marques with two variants, so two bays of the same marque can still look different. You can read what is in your bays from the arena instead of the menu. Damage, cadence, reach and the rarity colour are all exactly what they were; only the art changed.'],
      ] },
      { k: 'FIXED', c: '#8fc4ff', rows: [
        ['\ud83c\udfc6', 'Your Voidmaw season prize looked like it said you had won the mothership', 'The season-1 payout is collected after the new season opened, and the receipt was headed <b>\u201cTHE PROGENITOR FINAL\u201d</b> \u2014 the current season\u2019s name, on last season\u2019s prize. It reads as winning the ship. <b>Your Event Coins and LootCoins were always paid in full</b>, no hull was ever part of that prize, and nothing was taken from you. The receipt now names the season you actually placed in.'],
        ['❖', 'The Progenitor was handed out by mistake — and your parts are back', 'If you were holding <b>1,000 or more parts</b> banked from last season, the event assembled the mothership for you the moment you opened it and took the parts. Nobody was meant to be given that hull for a carried-over balance, so it has been <b>withdrawn</b> — and <b>every part is back in your inventory, in full</b>. If this happened to you there is a letter in your mail. You did nothing wrong, and nothing else on your account was touched. The mothership is unlocked by <b>choosing</b> to spend the 1,000 parts — the button is waiting on the event screen when your bar is full.'],
        ['❖', 'The Progenitor’s part bar showed the wrong number', 'Its card in the Hangar read <b>0 / 1,000</b> however many parts you were actually holding — it was reading the wrong pool. It shows your real total now.'],
        ['⚑', 'FLY NOW no longer sits on top of the Bridge', 'The deploy button was pinned near the top of the screen while the Bridge scrolled underneath it, so it covered your third hull slot and whatever else passed behind it. With the Bridge open it now sits at the bottom, above your tabs — always one tap away, never over anything.'],
        ['⚑', 'Systems you no longer own could still fill your cap', 'A system you lost or released could stay on your own map forever — counted against your system cap and shown in your totals, but gone as far as the rest of the galaxy was concerned. Pilots near their cap were refused new captures because of ground they did not hold. Those are now cleared on the next sync with the shared map, and the game is deliberately careful about it: it will not touch anything while the map is still loading, it never removes a system with a <b>citadel</b> on it, it leaves Void spires and House Citadels alone, it ignores anything you captured in the last couple of minutes, and if a large share of your empire looks missing it assumes the map is wrong rather than your save and changes nothing. <b>It can only ever release a system the galaxy already says is not yours.</b>'],
        ['⚑', 'The old claim-repair no longer re-takes lost ground', 'A one-time repair from months ago re-sent your local claims to the server whenever it found some missing. The problem it was written for is long fixed, and it had become the cause of the one above — quietly re-claiming systems that had since been lost to other pilots, pushing them past their cap and freezing their captures. Retired.'],
        ['☁', 'Progress can no longer be lost when two devices disagree', 'When the game folds a save from another device into the one you are playing, anything it does not explicitly know how to combine is decided by picking one copy whole — and the other copy’s version is gone. Several systems were never on that list. <b>Applied Prism Auras and forged Prism Cores</b> could vanish that way (the ingots they came from were already protected, but the cores and auras were not), along with your <b>Cargo Defense lifetime record</b> and your <b>mission boards</b>. All of them are now combined properly: an aura you applied stays applied, a core you forged stays forged, lifetime records keep the higher figure, and a claimed order can never un-claim itself. The <b>Friendship and Alliance store</b> weekly limits are counted the same way, so they can no longer be reset by switching devices — your points and everything you have already bought are untouched.'],
        ['◈', 'A razed fortress cannot come back through a device sync', 'Last build stopped razed natural citadels regenerating as full ×1000 fortresses on load. The <b>record</b> of which ones you razed could still be dropped when a save came in from another device — and once it was gone, the tile grew its fortress back and started paying fortress income again. Razings are now merged from both copies: razed on either device means razed. <b>Nothing has been taken off your account</b> and no system changed hands.'],
        ['⚔', 'The weekly Dreadnaught hunt can’t be reset by switching devices', 'One hunt per tier per week is the rule, and ascending could no longer get around it — but syncing from a device that had not run the hunt yet still handed the whole tier back. Spent attempts, Pro attempts and paid respawns now all survive the sync. This closes an exploit; <b>nothing you have already earned is affected</b>.'],
        ['⚑', 'Releasing a system, then ascending, no longer haunts you', 'Walking away from a system bars you from re-taking it for 24 hours, and that record was thrown away by an ascension. The result was a system you deliberately gave up quietly reappearing as yours — and a war report in your mail when somebody else took it. The clock now survives an ascension, like every other calendar in the game.'],
        ['⚑', 'Two badge chains counted things they said they didn’t', '<b>Galactic Conqueror</b> counts “galaxy tiles captured” and was including the neutral Home Citadel every account starts with, your Void spires and your casino House Citadels — and the spires were counted twice, since <b>Warden of the Void</b> sits right below it and exists to count them. The citadel chain had the same fault. Both count galaxy ground only now. <b>Your existing progress is kept as a floor</b>: no bar moves backwards and no badge you have claimed is affected — only new records are measured honestly.'],
        ['⚡', 'Rules that were invisible on a phone', 'The Voidmaw extra-attempt button hid “price triples with each purchase” in a hover tooltip, which a touch device can never show — so the second attempt cost three times what you expected with no warning. A shielded system in the galaxy list showed a bare countdown with no indication of what it meant. Both now say so on screen.'],
        ['🏰', 'The Home Citadel deploy button now says what a loss costs', 'Losing a wave only pauses mining until repairs — your wave, your gear and your hull are all safe — but the only place that said so was the how-to card you see once. It is on the deploy button now, next to the decision it belongs to. The endless AUTO-DEFENSE button already carried its own (heavier) warning and is unchanged.'],
        ['🏰', 'The Home Citadel guide still described the old wave rule', 'Last build changed raider strength so that getting stronger actually helps you push deeper — and the mode’s own rules card still said waves scale with your fleet. It now describes what the mode actually does.'],
        ['◈', 'A razed fortress stopped paying fortress income', 'A natural citadel you had <b>razed</b> could quietly go back to paying full fortress output — a thousand times a normal system — for the rest of a session. The map is rebuilt from scratch every time the game loads, and your razings are replayed onto it afterwards; when a save came in from another device mid-session the map was rebuilt without that replay, so those systems came back as the fortresses they used to be. The replay now runs on <b>every</b> path that rebuilds the map. <b>Nothing has been taken off your account</b>: no system changed hands, no citadel you still hold was touched, and every resource already banked is yours.'],
        ['🌌', 'Void spires and House Citadels are outside your system cap', 'If you were near your galaxy cap, warping into a Void spire failed with a bare <b>Warp Failed</b> — no shield, no cooldown, no reason given. The seven spires and the three casino holds were each eating one of your <b>50 galaxy systems</b>, and once the total reached the cap the game refused every trip, including the trip into the Void itself. The cap counts <b>galaxy systems only</b> now, the way it always read on the tin. If you hold spires or House Citadels you have that many free slots back on your next load, and you can take Void ground with a full galaxy empire.'],
        ['⚑', 'The My Galaxy board counts the systems you actually took', 'Your systems figure on that board included the neutral <b>Home Citadel</b> that every account is given, plus any Void spires and House Citadels you hold — so it could read eleven higher than the empire you can point at on the map, and it disagreed with the number on your own galaxy screen. The board and the game now count the same thing. Ranks shift slightly as a result: they are now sorted on galaxy ground, which is what the board is for.'],
        ['🏰', 'Empire Income stops counting a damaged Home Citadel', 'The income card added your Home Citadel’s hourly production into the headline totals even while the row underneath it said the base was damaged and mining had stopped — so the one number promising “every hour, whether you play or not” was counting a source that was paying nothing. A damaged base reads zero until repairs finish, and the row still shows so you know it is there.'],
        ['⬡', 'Command no longer hides your tabs on desktop', 'Opening Command covered the whole window, tab bar included, so the ✕ was the only way out. On a desktop-sized window the sheet now stops above your tabs: they stay visible and clickable, and tapping one closes Command on the way through. On a phone the sheet is unchanged — it needs the height.'],
        ['⚔', 'No more war reports for systems you lost weeks ago', 'Mail was arriving to say a system had fallen while you were away — for systems last held a month earlier, often in the first rings of the galaxy. Your own copy of the map can hold a claim the shared galaxy never accepted, or one already lost on another device, and the hourly reconciliation could not tell those from a system taken from you overnight, so it filed a war report for all of them. A loss is now only reported when it can actually be dated as recent, and a system is never reported twice. An out-of-date claim is corrected on the map in silence, as it should have been all along. Nothing about what you hold has changed — this was always about the mail, never the map.'],
        ['⚡', 'The zone list no longer freezes the game', 'The deeper you got, the worse it was, until the tab stopped answering altogether: the Zone Grind list was drawing every zone you had ever unlocked, all at once, every time it opened — seven hundred planets and their labels for a pilot deep in the game, rebuilt on every refresh. It now opens on the stretch of space around your frontier, with your recommended zone and the zone you are standing in always in view, and an <b>⏶ EARLIER ZONES</b> button at the top that loads older ground a chunk at a time and keeps your place when it does. Every zone is still reachable and nothing about a zone changed.'],
        ['◇', 'Aegis projectors really do auto-sell now', 'The last build bounded this and did not finish it. If you owned an Aegis with a projector fitted, every better projector that ever dropped was kept for ever — a hull in the hangar is never re-fitted by itself, so the piece it was compared against never improved and the hold never stopped growing. A parked hull now holds <b>one</b> candidate per mount, the best one, exactly as an empty mount does. Anything only that hull can mount is still kept; nothing fitted, and nothing above your auto-sell rarity, is ever touched. The same applies to fighter bays for a carrier you own but are not flying.'],
        ['▶', 'AUTO stays off when you change zone', 'Switching autopilot off and then warping somewhere else switched it back on under you, every time. The choice now holds for the rest of your session — change zones, open menus, come back to the arena, and it is still off. A fresh load still starts in autopilot, which is the default an idle game should have, and events that require manual flight are unchanged.'],
        ['●', 'Cargo Defense prints gold in gold — and the right number of cores', 'The payout line on every shipment card was painted green, on the one screen where gold is the whole point. It is gold now. The <b>◇ Dread Core</b> and <b>◈ LootCoin</b> figures on the manifest were also quoting the old rates — cores about three times what a run actually pays, LootCoins double — because those two lines were not updated when the payouts were. Every figure on the sheet is now the same arithmetic the run pays out. The run itself is unchanged: nothing was nerfed here, the card was simply lying.'],
        ['🛡', 'A system on the galaxy’s rim says so', 'A hold on the outer edge of the map, ringed by your own space on every side that has ground at all, still reported borders “facing open space” and told you to fill them — which is impossible, because the space out there is off the map. The rim has always been deliberately open, so no amount of territory can seal it; the sheet now says that plainly instead of giving you advice you can follow to the end and still be refused. It also separates the two cases, so a front line you <i>can</i> close still tells you to close it.'],
        ['◈', 'Void spires no longer count as galaxy citadels', 'Your citadel total counted Void spires and the casino House Citadels alongside the fortresses you hold in the galaxy, so the figure on the build sheet and on the Territory board was larger than the map you could point at. The count is galaxy fortresses only now, everywhere it appears. You have not lost a spire — the Void is its own screen and keeps paying exactly what it paid.'],
        ['⬡', 'The Pilot Tree map is not wallpapered in ◇ 1 chips any more', 'Every reachable node carried a little amber cost chip, and almost every node in the tree costs exactly one core — so the map wore forty identical chips in a ring around your unlocked area, telling you nothing and hiding the tree behind them. The chip is kept where it says something: the rare <b>◇ 3</b> nodes and whichever node you have selected. Node names still come in as you zoom, and every cost is still printed on the detail card and on every row of the list view.'],
        ['◱', 'Landscape is playable again', 'Turning a phone sideways handed you the <b>desktop</b> HUD on a screen a third the height: two full-size store buttons stacked above your score, a full-height tab bar, and the arena squeezed to half the window. The compact HUD now follows the <b>height</b> of your screen rather than its width, so it applies rotated as well as on a small phone, and your <b>hull bar is back in landscape</b> — it was being hidden outright to save room. Tabs also clear the notch on a phone held sideways.'],
        ['▲', 'Your fighters are craft again, not arrows', 'On some sessions every fighter in the wing drew as a flat coloured arrowhead. The ten new airframes were being fetched all at once at startup, and if one of those downloads dropped, that marque was written off for the rest of the session and fell back to the placeholder shape. Art now loads when a bay of that marque first launches, a failed download is retried, and a craft whose own frame has not arrived draws the old heavy fighter rather than a triangle.'],
        ['⚔', 'A refused attack tells you why', 'Tapping <b>Capture</b> or <b>Siege Citadel</b> on a system too deep for you did nothing at all — no message, no movement. The reason was being written to the battle feed <i>underneath</i> the sheet you were looking at, so it was invisible. Every refusal now appears in the sheet itself, and a system outside your level band says so before you tap: you can fly up to <b>10 levels</b> above yourself, and the card prints the level it opens at. The button itself also reads as unavailable now rather than staying lit — at capacity, behind an attack shield, out of level band or sealed, it says which and does not invite the tap. This also applies to a system you already hold — after an ascension your own deep holds are out of range for a while, they keep paying the whole time, and the sheet now says that instead of offering a dead button.'],
        ['\u25c7', 'Two devices no longer refund a Pilot Tree', 'If the game was open in two places at once, a node bought in one of them could be kept while the Dread Cores it cost were handed back by the other \u2014 so the same cores bought the same tree over and over. You still never lose a node to a stale login: when the two copies are reconciled every node is kept, and the cores it cost are now taken once. Nothing already unlocked has been touched.'],
        ['\u25ce', 'Ascending no longer resets your expeditions flown', 'The Exploration board ranks a career total, but the count was being cleared every time you ascended \u2014 so a pilot with stars read a handful of runs however many they had flown. Expeditions flown, your strongest wing ever sent, every hull\u2019s survey rank and any mission still in flight all ride through ascension now.'],
        ['\u2727', 'What was already lost stays lost', 'We cannot rebuild a count the reset deleted \u2014 the only record of it was the save it was wiped from. Your board climbs from where you stand today, and it will not drop again. If your standing matters to you, contact support and we will look at your account.'],
        ['\u25c7', 'Aegis field projectors have an icon, and auto-sell again', 'The four projectors and the Warden Array drew no icon at all on devices without those symbols in their fonts. Auto-sell also judged them as if they were cannons, so they could never be cleared out of the hold. They now sell like anything else you cannot use \u2014 and are always kept while you own a hull that can mount one, even if you are not flying it.'],
        ['\u25c8', 'My Systems counts built and natural citadels apart', 'The header printed a single \u201ccitadels\u201d figure that mixed the fortresses you built with the ones that came with the tile, so it never agreed with the rows underneath it. It states both now.'],
        ['\u26a1', 'Menus open straight away on phones', 'Tapping between Battle, Zone Grind and Loot could hang for a moment on a phone while nothing appeared to happen. Three things were in the way: the Loot screen drew a card for every item in your hold, the arena kept painting for a fraction of a second after you left it, and the screen you tapped had to finish building itself before the switch could be drawn at all. A very full hold now shows its top 200 with a button to open the rest, the arena stops the instant a menu opens, and the screen change is drawn first and filled a frame later. The fight itself is untouched \u2014 nothing about the simulation, your progress or your hold changed.'],
        ['\u25c7', 'Auto-sell sells again', 'If you set <b>Sell on pickup</b> and watched your hold fill up regardless, this is why: one empty weapon mount anywhere in your fleet \u2014 an escort you had never fitted, a hull parked in the hangar \u2014 counted <i>every</i> matching drop as something the fleet could use, so nothing was ever sold, at any rarity. An empty mount now holds <b>one</b> piece, the best one for it \u2014 and only mounts on the hull you are flying and the escorts flying with you. Hulls parked in the hangar no longer reserve gear your active fleet can already use, which is what was still filling holds on big accounts: dozens of owned hulls meant hundreds of permanently reserved slots. Anything only a parked hull can mount \u2014 an Aegis projector while you fly something else \u2014 is still kept. Anything that beats gear you actually have fitted is still kept exactly as before, and nothing equipped or bought is touched. If you have been flying with a full hold, expect it to clear on your next run.'],
        ['\u2708', 'Ascending actually disbands your wing', 'After an ascension your old escorts kept flying alongside you \u2014 endgame hulls in formation around a Level 1 starter frigate, still firing, still pulsing repairs. The wing had been disbanded correctly everywhere except on screen: nothing rebuilt the formation, so the ships already in the air simply stayed there. The wing now clears the instant the reset lands. Nothing about what you keep has changed \u2014 <b>every hull is still yours</b>, upgrade levels and Ship Ascension intact, waiting in the Hangar.'],
        ['\u2756', 'The ascension screens name the hull you really start in', 'The confirm screen showed your current flagship and told you that you warp out in it. You do not \u2014 a new run starts in the starter hull, and has for a while. Those screens now show that hull and say so plainly, and the keep/lose ledger lists the flagship change next to the wing. A wording fix: what ascending does to your account is unchanged.'],
        ['\u2709', 'Daily ladder awards arrive without a reload', 'If you left the game open across midnight UTC, your placings from the day before could sit unsent until you next signed in. The game was asking for them in the few minutes before the server had finished working the day out, treating the empty answer as final, and not asking again. It now keeps asking until they land. Nothing was ever lost \u2014 it was waiting.'],
        ['\u26d3', 'Natural fortresses show up under \u26d3 Citadels', 'The Citadels filter in the galaxy list only ever matched citadels a player built, or an enemy one you could go and attack \u2014 so a natural fortress sitting on a system you already hold matched neither and vanished from the list. All three now appear, and they are told apart on sight: \u26d3 in gold is yours, \u26d3 in amber belongs to another pilot, \u26f4 is the natural fortress that came with the ground. Your own citadel prints its rank now too.'],
        ['\u2630', 'The map / list switch is findable', 'Both the galaxy and the Pilot Tree could always be read as a searchable list instead of a map, and almost nobody knew \u2014 the control was a small two-part toggle among a row of identical chips, explained only by a tooltip that a phone never shows. It is now shown as a lit switch with both views on it, glowing until you use it \u2014 and on the Pilot Tree it tells you how many nodes you can afford right now.'],
        ['\u25a4', 'The Pilot Tree list is readable on a phone', 'On a phone the list view spent most of the screen on its own header and left room for about one node \u2014 in a small scroll box, inside a page that also scrolled, so dragging moved the wrong thing. The header is one row now, the list runs down the page like any other list, and the map gets a proper box instead of whatever height was left over.'],
        ['\u25b6', 'Autopilot is on every time you deploy', 'If you had ever switched autopilot off by hand \u2014 even once, even by accident \u2014 that choice was saved permanently, and every deployment afterwards dropped you into a zone with your fleet sitting still and nothing explaining why. Switching it off now lasts only for the fight you are in; deploying again brings it back. A stray tap on the pill while you were leaving another screen could also flip it off unnoticed, and that no longer counts.'],
      ] },
    ],
  };

  const KEY = 'lf_patch_seen';   // localStorage, NOT the save — a device fact.
  function seen() { try { return (localStorage.getItem(KEY) | 0); } catch (e) { return 0; } }
  function mark(b) { try { localStorage.setItem(KEY, String(b | 0)); } catch (e) {} }

  // A BRAND NEW PLAYER MUST NOT SEE PATCH NOTES. They were not here for the old
  // build, so "battle speed is now three tiers" is meaningless — it is simply
  // how the game works. First run records the build as seen and shows nothing.
  function isNewPlayer() {
    try {
      const s = window.GAME && window.GAME.state;
      if (!s) return true;
      return (s.level | 0) <= 1 && !(s.ascTotal | 0) && !(s.pasc && (s.pasc.stars | 0));
    } catch (e) { return true; }
  }

  function rowHTML(r) {
    return '<div class="pn-r"><i>' + r[0] + '</i><span><b>' + r[1] + '</b>' + r[2] + '</span></div>';
  }
  function show(force) {
    if (document.getElementById('pn-wrap')) return;
    const n = NOTES;
    const body = n.groups.map((g) =>
      '<div class="pn-g" style="--c:' + g.c + '"><div class="pn-k">' + g.k + '</div>' +
      g.rows.map(rowHTML).join('') + '</div>').join('');
    const w = document.createElement('div');
    w.id = 'pn-wrap';
    w.innerHTML =
      '<div class="pn-card" role="dialog" aria-label="What\u2019s new">' +
        '<div class="pn-head"><span class="pn-b">' + n.title + '</span>' +
          '<span class="pn-t">WHAT\u2019S NEW</span></div>' +
        '<div class="pn-sub">' + n.sub + '</div>' +
        '<div class="pn-body">' + body + '</div>' +
        '<button class="pn-ok" id="pn-ok">GOT IT</button>' +
      '</div>';
    document.body.appendChild(w);
    const close = () => { mark(BUILD); w.remove(); };
    w.querySelector('#pn-ok').addEventListener('click', close);
    // Tapping the backdrop closes too, and STILL marks it seen — a player who
    // dismisses it has made a choice; re-showing next session is nagging.
    w.addEventListener('click', (e) => { if (e.target === w) close(); });
    if (!force) mark(BUILD);   // marked on show, so a refresh cannot re-trigger it
  }

  function maybeShow() {
    if (seen() >= BUILD) return;
    if (isNewPlayer()) { mark(BUILD); return; }
    show(false);
  }

  // Wait for the game to be up (so isNewPlayer reads a real save) and for the
  // player to be past the login screen — a patch card over a login form is just
  // an obstacle. The update gate outranks it: if a newer build is being forced,
  // that message is the one that matters.
  function boot() {
    let tries = 0;
    const t = setInterval(() => {
      if (++tries > 40) { clearInterval(t); return; }     // ~20s, then give up quietly
      try {
        if (!window.GAME || !window.GAME.state) return;
        const login = document.getElementById('screen-login');
        if (login && login.classList.contains('active')) return;
        if (document.querySelector('.uv-wrap')) return;
        clearInterval(t);
        maybeShow();
      } catch (e) { clearInterval(t); }
    }, 500);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();

  window.PATCHNOTES = {
    show: () => show(true),
    NOTES,
    _reset: () => { try { localStorage.removeItem(KEY); } catch (e) {} },
  };
})();
